mapper.select:
SELECT result.* FROM ( SELECT b.id, b.name, b.is_leaf, b.status, b.del_flag, b.longitude, b.latitude, b.altitude, b.address, b.area, b.line, b.admin_dept, b.weight, b.video_feed, b.root_object_id, b.root_property_id, b.remark, b.create_by, b.create_time, b.update_by, b.update_time, pb.id as parent_id, pb.name as parent_name, o.parent_id as parent_object_id FROM bi_building b LEFT JOIN bi_object o ON b.root_object_id = o.id AND o.del_flag = '0' LEFT JOIN bi_template_object t ON o.template_object_id = t.id AND t.del_flag = '0' LEFT JOIN bi_building pb ON pb.root_object_id = o.parent_id AND pb.del_flag = '0'
b.del_flag = '0' AND b.is_leaf = '1' AND ( b.root_object_id IS NULL OR o.id IS NULL OR o.template_object_id IS NULL OR t.id IS NULL ) and b.name like concat('%', #{name}, '%') and b.status = #{status} and b.area = #{area} and b.line = #{line} and b.admin_dept = #{adminDept}
UNION
SELECT DISTINCT pb.id, pb.name, pb.is_leaf, pb.status, pb.del_flag, pb.longitude, pb.latitude, pb.altitude, pb.address, pb.area, pb.line, pb.admin_dept, pb.weight, pb.video_feed, pb.root_object_id, pb.root_property_id, pb.remark, pb.create_by, pb.create_time, pb.update_by, pb.update_time, null as parent_id, null as parent_name, null as parent_object_id FROM bi_building b JOIN bi_object o ON b.root_object_id = o.id AND o.del_flag = '0' LEFT JOIN bi_template_object t ON o.template_object_id = t.id AND t.del_flag = '0' JOIN bi_building pb ON pb.root_object_id = o.parent_id AND pb.del_flag = '0' AND pb.is_leaf = '0'
b.del_flag = '0' AND b.is_leaf = '1' AND ( o.template_object_id IS NULL OR t.id IS NULL ) and b.name like concat('%', #{name}, '%') and b.status = #{status} and b.area = #{area} and b.line = #{line} and b.admin_dept = #{adminDept}
) result ORDER BY result.is_leaf, result.id

